// Ship the library's existing browser mechanics inside the unpacked extension.
// Generated files are checked in so loading the recorder needs no build step.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.dirname(fileURLToPath(import.meta.url));
const runtime = fs.readFileSync(path.join(root, '../src/treadway/browser/browser-form.function.js'), 'utf8');
const binding = fs.readFileSync(path.join(root, '../src/treadway/browser/choice-binding.js'), 'utf8');
const header = '// GENERATED by node recorder/build-runtime.mjs from the Treadway library. Do not edit.\n';
for (const [file, source] of Object.entries({
  'form-runtime.js': header + 'globalThis.TreadwayFormRuntime = ' + runtime.trim() + ';\n',
  'choice-binding.js': header + '(function () { const module = { exports: {} };\n' + binding + '\nglobalThis.TreadwayChoiceBinding = module.exports; })();\n',
})) {
  const target = path.join(root, 'lib', file);
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== source) throw new Error('Stale recorder runtime: run node recorder/build-runtime.mjs');
  } else fs.writeFileSync(target, source);
}
